from safety_evals.metrics import flags_in_window, monitor_flag_rate, pooled_flag_rate


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": None}, {"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 0.25


def test_monitor_flag_rate_all_none_is_zero():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty_is_zero():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_pooled_flag_rate_weights_transcripts_not_groups():
    # Group a: 1/1 flagged (rate 1.0). Group b: 0/3 flagged (rate 0.0).
    # Pooled: 1 flagged out of 4 transcripts = 0.25, not the mean of group rates (0.5).
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": False}, {"flagged": False}],
    }
    assert pooled_flag_rate(groups) == 0.25


def test_pooled_flag_rate_ignores_empty_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "empty": []}
    assert pooled_flag_rate(groups) == 0.5


def test_pooled_flag_rate_no_transcripts_is_zero():
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"a": [], "b": []}) == 0.0


def test_flags_in_window_last_days_entries():
    assert flags_in_window([1, 2, 3, 4, 5], 2) == 9  # 4 + 5


def test_flags_in_window_zero_days_is_zero():
    assert flags_in_window([1, 2, 3], 0) == 0


def test_flags_in_window_days_larger_than_list_sums_whole_list():
    assert flags_in_window([1, 2, 3], 10) == 6

